function normalizeState(s){
  s=s||{};
  s.samples=(s.samples||[]).filter(x=>x&&x.codigo&&normalizeKey(x.codigo)!=='codigoamostra'&&normalizeKey(x.os)!=='ordemdeservicoos');
  s.mappings=s.mappings||{};s.leaders=s.leaders||{};s.extraCollectors=s.extraCollectors||[];
  s.freights=s.freights||[];s.freights.forEach(f=>{if(!Array.isArray(f.os))f.os=String(f.os||'').split(',').map(x=>x.trim()).filter(Boolean);if(!Array.isArray(f.contratos))f.contratos=String(f.contratos||'').split(',').map(x=>x.trim()).filter(Boolean);});
  s.imports=Array.isArray(s.imports)?s.imports:[];s.receivedRegistry=s.receivedRegistry||{};s.saoPedroEntradas=s.saoPedroEntradas||[];
  s.saoPedroEntradas.forEach(e=>{if(!Array.isArray(e.alocacoes)){e.alocacoes=e.dataColetaRef?[{dataColetaRef:e.dataColetaRef,quantidade:Number(e.quantidade)||0}]:[];}e.alocacoes=e.alocacoes.map(a=>({dataColetaRef:a.dataColetaRef||a.data||'',quantidade:Number(a.quantidade)||0})).filter(a=>a.dataColetaRef&&a.quantidade>0);e.dataColetaRef=e.alocacoes.length===1?e.alocacoes[0].dataColetaRef:'';});
  s.conventionalPlans=s.conventionalPlans||{};s.conventionalContractPlans=s.conventionalContractPlans||{};s.manualFieldReference=(s.manualFieldReference===undefined||s.manualFieldReference===null)?'':s.manualFieldReference;s.samples.forEach(x=>{if(x.recebidaSond===undefined)x.recebidaSond=false;if(!x.statusLogistico)x.statusLogistico='COLETADA';});s.lastUpdate=s.lastUpdate||new Date().toISOString();return s;
}
function loadState(){const saved=localStorage.getItem(KEY); if(saved){try{return JSON.parse(saved)}catch(e){}} const cleanSeed=SEED.filter(x=>x&&x.codigo&&normalizeKey(x.codigo)!=='codigoamostra');return {samples:cleanSeed,mappings:{},leaders:{},extraCollectors:[],freights:[],receivedRegistry:{},saoPedroEntradas:[],conventionalPlans:{},conventionalContractPlans:{},imports:[{file:'Amostras coletadas dia 02-09.xlsx',date:new Date().toISOString(),total:cleanSeed.length,newCount:cleanSeed.length,updated:0,type:'COLETAS'}],lastUpdate:new Date().toISOString()};}
function save(){state.lastUpdate=new Date().toISOString();try{localStorage.setItem(KEY,JSON.stringify(state));}catch(err){console.error('Erro ao gravar no localStorage:',err);alert('Não foi possível salvar no navegador. Gere um Backup e verifique o espaço de armazenamento do site. Detalhe: '+err.message);return false;}try{renderAll();}catch(err){console.error('Os dados foram salvos, mas houve erro ao atualizar a tela:',err);alert('Os dados foram salvos, mas houve um erro ao atualizar a tela. Atualize a página (Ctrl + F5). Detalhe: '+err.message);}return true;}
