function renderStockReconciliation(){
  const ss=filtered(),collected=ss.length,field=fieldInventoryForSamples(ss),atSede=estimatedAtSedeForSamples(ss);
  const manual=manualReceivedForSamples(ss),sond=sondReceivedForSamples(ss);

  const el=document.getElementById('reconcileKpis');
  if(el)el.innerHTML=[
    ['Coletadas',collected,''],['Manual validado',manual,''],['Recebidas Sond',sond,''],['Consideradas na sede',atSede,''],['Campo estimado',field,'']
  ].map(([l,n,c])=>`<div class="reconcile-box ${c}"><small>${l}</small><b>${n}</b></div>`).join('');

  const ref=document.getElementById('manualFieldReference');
  if(ref&&document.activeElement!==ref)ref.value=state.manualFieldReference??'';
  const diff=document.getElementById('manualFieldDifference');
  if(diff){
    if(state.manualFieldReference!==''&&!isNaN(Number(state.manualFieldReference))){
      const d=field-Number(state.manualFieldReference);
      diff.innerHTML=d===0?`<span class="diff-ok">✓ O campo estimado confere exatamente com sua contagem manual.</span>`:`<span class="diff-warn">Dashboard: <b>${field}</b> • Sua contagem: <b>${state.manualFieldReference}</b> • Diferença: <b>${d>0?'+':''}${d}</b>. ${d<0?'O dashboard encontrou mais recebimentos do que sua contagem manual indicava.':'O dashboard ainda considera mais amostras em campo.'}</span>`;
    }else diff.textContent='Sua contagem manual é apenas uma referência de conferência.';
  }

  const scopeOS=new Set(ss.map(x=>x.os));
  const rows=[...scopeOS].map(os=>{
    const osRows=ss.filter(x=>x.os===os),total=osRows.length;
    const manualOS=manualReceivedForSamples(osRows),sondOS=sondReceivedForSamples(osRows),sedeOS=estimatedAtSedeForSamples(osRows),fieldOS=fieldInventoryForSamples(osRows);
    const client=osRows.find(x=>x.cliente)?.cliente||'—';
    const beyond=Math.max(0,sondOS-manualOS),manualAhead=Math.max(0,manualOS-sondOS);
    let note='<span class="badge green">Manual = Sond</span>';
    if(beyond)note=`<span class="badge red">Sond +${beyond} além do manual</span>`;
    else if(manualAhead)note=`<span class="badge orange">Manual +${manualAhead} aguardando Sond</span>`;
    return {os,client,total,manualOS,sondOS,sedeOS,fieldOS,note};
  }).sort((a,b)=>(b.sondOS-b.manualOS)-(a.sondOS-a.manualOS)||b.fieldOS-a.fieldOS);

  const body=document.getElementById('stockAuditRows');
  if(body)body.innerHTML=rows.length?rows.map(r=>`<tr><td><b>${esc(r.os)}</b></td><td>${esc(r.client)}</td><td>${r.total}</td><td>${r.manualOS}</td><td>${r.sondOS}</td><td><b>${r.sedeOS}</b></td><td><b>${r.fieldOS}</b></td><td>${r.note}</td></tr>`).join(''):'<tr><td colspan="8" class="empty">Sem dados no filtro atual.</td></tr>';
}
