function saoPedroAllocationRows(){return [...document.querySelectorAll('.sp-alloc-qty')].map(i=>({dataColetaRef:i.dataset.date,quantidade:Math.max(0,Math.trunc(Number(i.value)||0))})).filter(a=>a.quantidade>0);}
