function convDepthKey(v){if(v===null||v===undefined||v==='')return'';const n=Number(v);return Number.isFinite(n)?n.toFixed(3):normText(v);}
function convBatchKey(os,date){return `${String(os||'').trim()}|||${isoFromBR(date)||String(date||'')}`;}
function convDomKey(os,date){return normalizeKey(`${os}_${isoFromBR(date)||date||'semdata'}`)||'conv';}
function conventionalGroupKey(s){return `${normText(s.identificacao)}|||${convDepthKey(s.topo)}|||${convDepthKey(s.baseM)}`;}
function conventionalGroups(samples){
  const by={};(samples||[]).forEach(s=>{const k=conventionalGroupKey(s);if(!by[k])by[k]={identificacao:s.identificacao||'—',topo:s.topo,baseM:s.baseM,samples:[]};by[k].samples.push(s);});
  return Object.values(by).map(g=>{const n=g.samples.length;const dosage=n>5;return {...g,count:n,dosage,caracterizacao:1,compactacao:dosage?1:n};}).sort((a,b)=>String(a.identificacao).localeCompare(String(b.identificacao),'pt-BR',{numeric:true}));
}
function conventionalFieldSamplesAll(){return estimatedFieldSamplesAll();}
