  ss.forEach(s=>{const d=isoFromBR(s.dataColeta)||s.dataColeta||'';const k=convBatchKey(s.os,d);if(!by[k])by[k]={key:k,os:s.os,date:d,cliente:s.cliente,contrato:s.contrato||'',samples:[]};by[k].samples.push(s);});
  return Object.values(by).map(b=>{const groups=conventionalGroups(b.samples);const autoChar=groups.reduce((a,g)=>a+g.caracterizacao,0);const autoComp=groups.reduce((a,g)=>a+g.compactacao,0);const dosageGroups=groups.filter(g=>g.dosage).length;const plan=state.conventionalPlans?.[b.key]||{};const hasChar=plan.caracterizacao!==null&&plan.caracterizacao!==undefined&&plan.caracterizacao!=='';const hasComp=plan.compactacao!==null&&plan.compactacao!==undefined&&plan.compactacao!=='';const finalChar=hasChar?Number(plan.caracterizacao):autoChar;const finalComp=hasComp?Number(plan.compactacao):autoComp;return {...b,groups,autoChar,autoComp,dosageGroups,plan,finalChar:Number.isFinite(finalChar)?finalChar:autoChar,finalComp:Number.isFinite(finalComp)?finalComp:autoComp,manual:hasChar||hasComp};}).sort((a,b)=>(b.date||'').localeCompare(a.date||'')||String(a.os).localeCompare(String(b.os),'pt-BR',{numeric:true}));
