  batches.forEach(b=>{const key=convContractKey(b.contrato,b.os);if(!by[key])by[key]={key,label:b.contrato||`Sem SUP • OS ${b.os}`,contrato:b.contrato||'',oss:new Set(),samples:0,autoChar:0,autoComp:0,baseChar:0,baseComp:0,dosageGroups:0,batches:[]};const g=by[key];g.oss.add(b.os);g.samples+=b.samples.length;g.autoChar+=b.autoChar;g.autoComp+=b.autoComp;g.baseChar+=b.finalChar;g.baseComp+=b.finalComp;g.dosageGroups+=b.dosageGroups;g.batches.push(b);});
  return Object.values(by).map(g=>{const p=state.conventionalContractPlans?.[g.key]||{};const hc=p.caracterizacao!==null&&p.caracterizacao!==undefined&&p.caracterizacao!=='';const hp=p.compactacao!==null&&p.compactacao!==undefined&&p.compactacao!=='';const finalChar=hc?Number(p.caracterizacao):g.baseChar;const finalComp=hp?Number(p.compactacao):g.baseComp;return {...g,osList:[...g.oss],plan:p,finalChar:Number.isFinite(finalChar)?finalChar:g.baseChar,finalComp:Number.isFinite(finalComp)?finalComp:g.baseComp,manualContract:hc||hp,manualBatch:g.batches.some(b=>b.manual)};}).sort((a,b)=>b.samples-a.samples||a.label.localeCompare(b.label,'pt-BR',{numeric:true}));
