function openSample(code){const s0=state.samples.find(x=>x.codigo===code);if(!s0)return;const s=enriched(s0);document.getElementById('modalTitle').textContent=`Amostra ${code}`;document.getElementById('modalBody').innerHTML=`<div class="details-grid"><div class="detail"><small>OS</small>${esc(s.os)}</div><div class="detail"><small>ST</small>${esc(s.identificacao)}</div><div class="detail"><small>Cliente</small>${esc(s.cliente)}</div><div class="detail"><small>Sondador</small>${esc(s.coletadoPor)}</div></div>${s.recebidaSond?`<div class="received-detail"><div class="item"><small>Status Sond</small><span class="badge green">✅ Recebida</span></div><div class="item"><small>Data / Hora Primeira Foto</small><span class="receipt-time">${esc(s.primeiraFotoSond||s.dataRecebimentoSond||'—')}</span></div><div class="item"><small>Data / Hora Última Foto</small><span>${esc(s.ultimaFotoSond||'—')}</span></div><div class="item"><small>Tag / Usuário</small><span>${esc(s.tagSond||'—')} • ${esc(s.usuarioRecebimentoSond||'—')}</span></div></div>`:''}<div class="form-grid"><div class="field"><label>Status logístico</label><select id="edStatus">${STAGES.map(x=>`<option value="${x}" ${x===s.statusLogistico?'selected':''}>${stageLabels[x]}</option>`).join('')}</select></div><div class="field"><label>Base logística</label><input id="edBase" value="${esc(s.baseLogistica||'')}" list="basesList"></div><div class="field"><label>Contrato/SUP</label><input id="edContract" value="${esc(s.contrato||'')}"></div><div class="field"><label>Frete</label><input id="edFreight" value="${esc(s.freteCodigo||'')}"></div><div class="field"><label>Saída da base</label><input type="date" id="edDeparture" value="${esc(s.dataSaida||'')}"></div><div class="field"><label>Previsão chegada</label><input type="date" id="edEta" value="${esc(s.dataPrevistaChegada||'')}"></div><div class="field"><label>Baixa manual — chegada São Pedro</label><input type="date" id="edArrival" value="${esc(s.dataChegada||'')}"></div><div class="field"><label>Recebimento manual</label><input type="date" id="edReceived" value="${esc(s.dataRecebimento||'')}"></div><div class="field"><label>Início ensaio</label><input type="date" id="edStart" value="${esc(s.dataInicioEnsaio||'')}"></div><div class="field"><label>Conclusão ensaio</label><input type="date" id="edDone" value="${esc(s.dataConclusao||'')}"></div><div class="field" style="grid-column:span 2"><label>Observação</label><textarea id="edObs">${esc(s.observacao||'')}</textarea></div></div><div style="display:flex;justify-content:flex-end;margin-top:14px"><button class="btn primary" onclick="saveSample('${escAttr(code)}')">Salvar alterações</button></div>`;showModal('detailsModal');}
function saveSample(code){const s=state.samples.find(x=>x.codigo===code);if(!s)return;s.statusLogistico=document.getElementById('edStatus').value;s.baseLogistica=document.getElementById('edBase').value.trim();s.contrato=document.getElementById('edContract').value.trim();s.freteCodigo=document.getElementById('edFreight').value.trim();s.dataSaida=document.getElementById('edDeparture').value;s.dataPrevistaChegada=document.getElementById('edEta').value;s.dataChegada=document.getElementById('edArrival').value;s.dataRecebimento=document.getElementById('edReceived').value;s.dataInicioEnsaio=document.getElementById('edStart').value;s.dataConclusao=document.getElementById('edDone').value;s.observacao=document.getElementById('edObs').value;save();hideModal('detailsModal');toast('Amostra atualizada');}
