function showModal(id){document.getElementById(id).classList.add('show')}
function hideModal(id){document.getElementById(id).classList.remove('show')}
function normalizeKey(k){return String(k||'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase().replace(/[^a-z0-9]/g,'')}
const colMap={ordemdeservicoos:'os',ordemdeservico:'os',identificacao:'identificacao',qtdadedeamostrasnestasondagem:'qtdSondagem',tomador:'cliente',codigoamostra:'codigo',rfid:'rfid',tipo:'tipo',status:'statusSond',topom:'topo',basem:'baseM',coletadopor:'coletadoPor',datadacoleta:'dataColeta',datadacriacao:'dataCriacao'};
function parseWorkbook(file){const reader=new FileReader();reader.onload=e=>{try{const wb=XLSX.read(e.target.result,{type:'array',cellDates:false});const ws=wb.Sheets[wb.SheetNames[0]];const raw=XLSX.utils.sheet_to_json(ws,{defval:''});const mapped=raw.map(r=>{const o={};Object.entries(r).forEach(([k,v])=>{const key=colMap[normalizeKey(k)];if(key)o[key]=v});return o}).filter(x=>x.codigo);if(!mapped.length)throw new Error('Não encontrei a coluna Código Amostra.');previewData=mapped.map(toSample);previewFilename=file.name;showPreview();}catch(err){alert('Não foi possível ler o Excel: '+err.message)}};reader.readAsArrayBuffer(file)}
function excelDate(v){if(!v)return'';if(typeof v==='number'){const d=XLSX.SSF.parse_date_code(v);return `${String(d.d).padStart(2,'0')}/${String(d.m).padStart(2,'0')}/${d.y}`;}return String(v).trim()}
function excelDateTime(v){
  if(v===null||v===undefined||v==='')return '';
  if(v instanceof Date && !isNaN(v)){
    return `${String(v.getDate()).padStart(2,'0')}/${String(v.getMonth()+1).padStart(2,'0')}/${v.getFullYear()} ${String(v.getHours()).padStart(2,'0')}:${String(v.getMinutes()).padStart(2,'0')}`;
  }
  if(typeof v==='number'){
    const d=XLSX.SSF.parse_date_code(v);
    if(!d)return String(v);
    return `${String(d.d).padStart(2,'0')}/${String(d.m).padStart(2,'0')}/${d.y} ${String(d.H||0).padStart(2,'0')}:${String(d.M||0).padStart(2,'0')}`;
  }
  const raw=String(v).trim();
  if(!raw)return '';
  // Mantém datas já formatadas no Excel, mas normaliza ISO quando possível.
  const iso=raw.match(/^(\d{4})-(\d{2})-(\d{2})[T\s](\d{2}):(\d{2})/);
  if(iso)return `${iso[3]}/${iso[2]}/${iso[1]} ${iso[4]}:${iso[5]}`;
  return raw;
}
function toSample(x){return {os:String(x.os||'').trim(),identificacao:String(x.identificacao||'').trim(),qtdSondagem:Number(x.qtdSondagem||0),cliente:String(x.cliente||'').trim(),codigo:String(x.codigo||'').trim(),rfid:String(x.rfid||'').trim(),tipo:String(x.tipo||'').trim(),statusSond:String(x.statusSond||'').trim(),topo:x.topo??'',baseM:x.baseM??'',coletadoPor:String(x.coletadoPor||'').trim(),dataColeta:excelDate(x.dataColeta),dataCriacao:excelDate(x.dataCriacao),lider:'',baseLogistica:'',contrato:'',statusLogistico:'COLETADA',freteCodigo:'',dataSaida:'',dataPrevistaChegada:'',dataChegada:'',dataRecebimento:'',dataInicioEnsaio:'',dataConclusao:'',observacao:'',recebidaSond:false,dataRecebimentoSond:'',tagSond:'',usuarioRecebimentoSond:'',primeiraFotoSond:'',ultimaFotoSond:'',qtdFotosSond:''}}
function showPreview(){document.getElementById('preview').classList.add('show');document.getElementById('previewName').innerHTML=`<b>${esc(previewFilename)}</b><br>Prévia antes de gravar neste navegador.`;document.getElementById('pvRecords').textContent=previewData.length;document.getElementById('pvST').textContent=new Set(previewData.map(x=>`${x.os}|${x.identificacao}`)).size;document.getElementById('pvOS').textContent=new Set(previewData.map(x=>x.os)).size;document.getElementById('pvClients').textContent=new Set(previewData.map(x=>x.cliente)).size;}
function normCode(v){return String(v||'').trim().toUpperCase();}
function applyReceivedToSample(s,r){if(!s||!r)return false;const was=!!s.recebidaSond;s.recebidaSond=true;s.statusSondLaboratorio='RECEBIDA';s.dataRecebimentoSond=r.primeiraFoto||r.ultimaFoto||s.dataRecebimentoSond||new Date().toLocaleString('pt-BR');s.tagSond=r.tag||s.tagSond||'';s.usuarioRecebimentoSond=r.usuario||s.usuarioRecebimentoSond||'';s.primeiraFotoSond=r.primeiraFoto||s.primeiraFotoSond||'';s.ultimaFotoSond=r.ultimaFoto||s.ultimaFotoSond||'';s.qtdFotosSond=r.qtdFotos||s.qtdFotosSond||'';if(!stageAtLeast(s.statusLogistico,'RECEBIDA'))s.statusLogistico='RECEBIDA';return !was;}
function applyReceivedRegistry(){const byCode=new Map(state.samples.map(x=>[normCode(x.codigo),x]));let applied=0;Object.values(state.receivedRegistry||{}).forEach(r=>{const s=byCode.get(normCode(r.codigo));if(s&&applyReceivedToSample(s,r))applied++;});return applied;}
function confirmImport(){if(!previewData)return;const byCode=new Map(state.samples.map(x=>[normCode(x.codigo),x]));let newCount=0,updated=0;const sourceFields=['os','identificacao','qtdSondagem','cliente','rfid','tipo','statusSond','topo','baseM','coletadoPor','dataColeta','dataCriacao'];previewData.forEach(n=>{const old=byCode.get(normCode(n.codigo));if(old){sourceFields.forEach(k=>{if(n[k]!==''&&n[k]!==undefined)old[k]=n[k]});updated++;}else{const mp=state.mappings[n.os]||{};if(mp.base)n.statusLogistico='NA_BASE';state.samples.push(n);byCode.set(normCode(n.codigo),n);newCount++;}});const receivedApplied=applyReceivedRegistry();state.imports.push({file:previewFilename,date:new Date().toISOString(),total:previewData.length,newCount,updated,type:'COLETAS',receivedApplied});previewData=null;document.getElementById('preview').classList.remove('show');document.getElementById('fileInput').value='';save();toast(`Importação: ${newCount} novas, ${updated} atualizadas${receivedApplied?` • ${receivedApplied} recebimentos Sond aplicados`:''}`);go('overview');}
const receivedColMap={codigodaamostra:'codigo',codigoamostra:'codigo',ordemdeservicoos:'os',ordemdeservico:'os',idsistema:'idSistema',identificacao:'identificacao',tipodaamostra:'tipo',rfid:'rfid',tag:'tag',tomadora:'cliente',datahoraprimeirafoto:'primeiraFoto',datahoraultimafoto:'ultimaFoto',quantidadedefotos:'qtdFotos',usuario:'usuario'};
function parseReceivedWorkbook(file){const reader=new FileReader();reader.onload=e=>{try{const wb=XLSX.read(e.target.result,{type:'array',cellDates:false});const ws=wb.Sheets[wb.SheetNames[0]];const raw=XLSX.utils.sheet_to_json(ws,{defval:''});const mapped=raw.map(r=>{const o={};Object.entries(r).forEach(([k,v])=>{const key=receivedColMap[normalizeKey(k)];if(key)o[key]=v});return o}).filter(x=>x.codigo);if(!mapped.length)throw new Error('Não encontrei a coluna Código da Amostra.');const parsed=mapped.map(x=>({codigo:String(x.codigo||'').trim(),os:String(x.os||'').trim(),identificacao:String(x.identificacao||'').trim(),tipo:String(x.tipo||'').trim(),rfid:String(x.rfid||'').trim(),tag:String(x.tag||'').trim(),cliente:String(x.cliente||'').trim(),primeiraFoto:excelDateTime(x.primeiraFoto),ultimaFoto:excelDateTime(x.ultimaFoto),qtdFotos:String(x.qtdFotos||'').trim(),usuario:String(x.usuario||'').trim()}));const counts={};parsed.forEach(x=>{const k=normCode(x.codigo);counts[k]=(counts[k]||0)+1});receivedPreviewDuplicates=Object.entries(counts).filter(([,n])=>n>1).map(([codigo,n])=>({codigo,n}));const uniqueMap=new Map();parsed.forEach(x=>{const k=normCode(x.codigo);if(!uniqueMap.has(k))uniqueMap.set(k,x)});receivedPreviewData=[...uniqueMap.values()];receivedPreviewFilename=file.name;showReceivedPreview();}catch(err){alert('Não foi possível ler o Excel de recebidas: '+err.message)}};reader.readAsArrayBuffer(file)}
function showReceivedPreview(){const codes=new Set(state.samples.map(x=>normCode(x.codigo)));const matched=receivedPreviewData.filter(x=>codes.has(normCode(x.codigo)));document.getElementById('receivedPreview').classList.add('show');const dup=receivedPreviewDuplicates.length;document.getElementById('receivedPreviewName').innerHTML=`<b>${esc(receivedPreviewFilename)}</b><br>Prévia do cruzamento. ${dup?`<span class="badge orange">⚠ ${dup} código(s) duplicado(s) no arquivo — será considerado 1 por Código Amostra.</span>`:'Sem códigos duplicados.'} Registros não encontrados ficarão guardados para cruzamento futuro.`;document.getElementById('rvRecords').textContent=receivedPreviewData.length;document.getElementById('rvMatched').textContent=matched.length;document.getElementById('rvMissing').textContent=receivedPreviewData.length-matched.length;document.getElementById('rvOS').textContent=new Set(matched.map(x=>x.os).filter(Boolean)).size;const d=document.getElementById('rvDuplicates');if(d)d.textContent=dup;}
function confirmReceivedImport(){
  if(!receivedPreviewData)return;
  if(receivedPreviewDuplicates.length&&!confirm(`⚠ O Excel contém ${receivedPreviewDuplicates.length} Código(s) de Amostra repetido(s). Cada código será considerado apenas uma vez. Deseja continuar?`))return;
  const beforeComplete=new Set(contractCompleteness(state.samples,true).filter(x=>x.status==='COMPLETO').map(x=>x.key));
  state.receivedRegistry=state.receivedRegistry||{};receivedPreviewData.forEach(r=>state.receivedRegistry[normCode(r.codigo)]={...r,codigo:normCode(r.codigo)});const byCode=new Map(state.samples.map(x=>[normCode(x.codigo),x]));let matched=0,missing=0,newlyApplied=0;receivedPreviewData.forEach(r=>{const s=byCode.get(normCode(r.codigo));if(!s){missing++;return;}matched++;if(applyReceivedToSample(s,r))newlyApplied++;});state.imports.push({file:receivedPreviewFilename,date:new Date().toISOString(),total:receivedPreviewData.length,newCount:0,updated:matched,missing,type:'RECEBIDAS'});receivedPreviewData=null;receivedPreviewDuplicates=[];document.getElementById('receivedPreview').classList.remove('show');document.getElementById('receivedFileInput').value='';save();
  const newlyComplete=contractCompleteness(state.samples,true).filter(x=>x.status==='COMPLETO'&&!beforeComplete.has(x.key));
  if(newlyComplete.length===1)toast(`✅ ${newlyComplete[0].label}: contrato completo na sede`);else if(newlyComplete.length>1)toast(`✅ ${newlyComplete.length} contratos ficaram completos na sede`);else toast(`Recebidas Sond: ${matched} cruzadas • ${newlyApplied} novas confirmações • ${missing} guardadas para cruzamento futuro`);go('recebidos');
}

function exportExcel(){const rows=state.samples.map(enriched);const wb=XLSX.utils.book_new();const sampleRows=rows.map(s=>({'Código Amostra':s.codigo,'OS':s.os,'ST':s.identificacao,'Cliente':s.cliente,'Sondador':s.coletadoPor,'Líder':s.lider||'','Data Coleta':s.dataColeta,'Contrato/SUP':s.contrato||'','Base Logística':s.baseLogistica||'','Status Logístico':stageLabels[s.statusLogistico]||s.statusLogistico,'Frete':s.freteCodigo||'','Baixa São Pedro':s.dataChegada||'','Recebida Sond':s.recebidaSond?'Sim':'Não','Data Recebida Sond':s.dataRecebimentoSond||'','Tag Sond':s.tagSond||'','Usuário Recebimento Sond':s.usuarioRecebimentoSond||''}));XLSX.utils.book_append_sheet(wb,XLSX.utils.json_to_sheet(sampleRows),'Amostras');const leaders=allCollectors().map(c=>({Sondador:c,Líder:state.leaders[c]||''}));XLSX.utils.book_append_sheet(wb,XLSX.utils.json_to_sheet(leaders),'Sondadores_Lideres');const maps=Object.entries(state.mappings||{}).map(([os,m])=>({OS:os,'Cliente':state.samples.find(x=>x.os===os)?.cliente||'',Base:m.base||'','Contrato/SUP (legado)':m.contrato||''}));XLSX.utils.book_append_sheet(wb,XLSX.utils.json_to_sheet(maps),'Bases_OS');const clientes=[];Object.entries(state.samples.reduce((acc,s)=>{const c=s.cliente||'SEM CLIENTE';(acc[c]||(acc[c]=[])).push(s);return acc},{})).forEach(([cliente,rows])=>{Object.entries(rows.reduce((a,s)=>{(a[s.os]||(a[s.os]=[])).push(s);return a},{})).forEach(([os,r])=>clientes.push({Cliente:cliente,OS:os,'Amostras':r.length,'Em campo':fieldInventoryForSamples(r),'Na sede':reconciledSedeForSamples(r)}))});XLSX.utils.book_append_sheet(wb,XLSX.utils.json_to_sheet(clientes),'Clientes');const fretesExport=(state.freights||[]).map(f=>({
  'Código frete':f.code||'',
  'Base origem':f.base||'',
  'Previsão chegada':f.eta||'',
  'Status':f.status||'',
  'OS no caminhão':(f.os||[]).join(', '),
  'Contratos/SUP no caminhão':(f.contratos||[]).join(', '),
  'Transportadora / motorista':f.carrier||'',
  'Quantidade amostras':state.samples.filter(s=>(f.os||[]).includes(s.os)).length
}));XLSX.utils.book_append_sheet(wb,XLSX.utils.json_to_sheet(fretesExport),'Fretes');const sp=(state.saoPedroEntradas||[]).map(x=>({'Data chegada':x.data,'Coleta referente':x.dataColetaRef||'','OS':x.os,'Contrato/SUP':x.contrato,'Base origem':x.base,'Quantidade':x.quantidade,'Observação':x.observacao}));XLSX.utils.book_append_sheet(wb,XLSX.utils.json_to_sheet(sp),'Sao_Pedro_Manual');const rr=receivedRegistryRows().map(r=>({'Código Amostra':r.codigo,'OS':r.os,'ST':r.identificacao,'Cliente':r.cliente,'Data/Hora Recebida':r.primeiraFoto||r.ultimaFoto,'Tag':r.tag,'Usuário':r.usuario,'Encontrada nas Coletas':r._sample?'Sim':'Não'}));XLSX.utils.book_append_sheet(wb,XLSX.utils.json_to_sheet(rr),'Recebidas_Sond');XLSX.utils.book_append_sheet(wb,XLSX.utils.json_to_sheet(state.imports||[]),'Importacoes');XLSX.utils.book_append_sheet(wb,XLSX.utils.json_to_sheet(conventionalExportRows()),'Pulmao_Convencionais');XLSX.writeFile(wb,`gestao-amostras-${new Date().toISOString().slice(0,10)}.xlsx`);}
function downloadBlob(name,content,type){const blob=new Blob([content],{type});const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),500);}
