function restoreBackupFile(file){const r=new FileReader();r.onload=e=>{try{const obj=normalizeState(JSON.parse(e.target.result));if(!obj.samples?.length)throw new Error('Backup sem amostras.');if(!confirm(`Restaurar backup com ${obj.samples.length} amostras? Os dados atuais serão substituídos.`))return;state=obj;save();toast('Backup restaurado com sucesso');}catch(err){alert('Não foi possível restaurar o backup: '+err.message)}};r.readAsText(file);}
function applyTheme(theme){const next=theme==='dark'?'dark':'light';document.documentElement.dataset.theme=next;try{localStorage.setItem(THEME_KEY,next)}catch(e){}syncThemeButton();setTimeout(()=>{renderTeamCharts();const ss=filtered(),facet=filterSamples('fBase'),g={};facet.forEach(x=>{const b=x.baseLogistica||'SEM BASE';(g[b]||(g[b]=[])).push(x)});const metrics=Object.entries(g).map(([base,rows])=>{const osSet=new Set(rows.map(x=>x.os));return {base,field:fieldInventoryForSamples(rows),os:osSet.size,contracts:new Set(rows.map(x=>x.contrato).filter(Boolean)).size};}).sort((a,b)=>b.field-a.field);renderBaseChart(metrics);},0);}
