document.getElementById('saveMapping').onclick=()=>{const os=document.getElementById('mapOS').value,base=document.getElementById('mapBase').value.trim();if(!os)return alert('Selecione uma OS.');if(!base)return alert('Informe a Base.');const prev=state.mappings[os]||{};state.mappings[os]={...prev,base,updatedAt:new Date().toISOString()};state.samples.filter(s=>s.os===os&&s.statusLogistico==='COLETADA'&&base).forEach(s=>s.statusLogistico='NA_BASE');if(save()){syncBaseMappingForm();toast(`Base da OS ${os} salva com sucesso`);}};
document.getElementById('saveFreight').onclick=()=>{
  const code=document.getElementById('frCode').value.trim(),
        base=document.getElementById('frBase').value.trim(),
        eta=document.getElementById('frEta').value,
        status=document.getElementById('frStatus').value,
        carrier=document.getElementById('frCarrier').value.trim(),
        oss=uniq(document.getElementById('frOS').value.split(',').map(x=>x.trim()).filter(Boolean)),
        contratos=uniq(document.getElementById('frContracts').value.split(',').map(x=>x.trim()).filter(Boolean));
  if(!code||!oss.length)return alert('Informe o código do frete e ao menos uma OS.');
  const duplicate=state.freights.some(x=>x.code===code&&x.code!==editingFreightCode);
  if(duplicate)return alert('Já existe outro frete com esse código.');

  if(editingFreightCode){
    const oldCode=editingFreightCode;
    const f=state.freights.find(x=>x.code===oldCode);
    if(!f)return alert('Frete não encontrado para edição.');
    const oldOS=[...(f.os||[])];

    // Desvincula amostras removidas do frete
    state.samples.filter(s=>s.freteCodigo===oldCode&&!oss.includes(s.os)).forEach(s=>{
      s.freteCodigo='';
      s.dataPrevistaChegada='';
      if(['FRETE_CONTRATADO','EM_TRANSITO'].includes(s.statusLogistico))s.statusLogistico=s.baseLogistica?'NA_BASE':'COLETADA';
    });

    Object.assign(f,{code,base,eta,status,carrier,os:oss,contratos,updatedAt:new Date().toISOString()});

    // Atualiza/relaciona as OS atuais
    state.samples.filter(s=>oss.includes(s.os)&&(s.freteCodigo===oldCode||!s.freteCodigo||oldOS.includes(s.os))).forEach(s=>{
      s.freteCodigo=code;
      if(base&&!s.baseLogistica)s.baseLogistica=base;
      s.statusLogistico=freightStatusForSample(status,!!s.baseLogistica);
      s.dataPrevistaChegada=eta;
    });

    // Se o código mudou, atualiza qualquer referência remanescente
    if(code!==oldCode)state.samples.filter(s=>s.freteCodigo===oldCode).forEach(s=>s.freteCodigo=code);

    save();
    resetFreightForm();
    toast(`Frete ${code} atualizado`);
  }else{
    state.freights.push({code,base,eta,status,carrier,os:oss,contratos,createdAt:new Date().toISOString()});
    state.samples.filter(s=>oss.includes(s.os)).forEach(s=>{
      s.freteCodigo=code;
      if(base&&!s.baseLogistica)s.baseLogistica=base;
      s.statusLogistico=freightStatusForSample(status,!!s.baseLogistica);
      s.dataPrevistaChegada=eta;
    });
    save();
    resetFreightForm();
    toast('Frete cadastrado');
  }
};
